//! Existing decision transport, real original owner, canonical receipts/drain.
use super::*;
use crate::pet_runtime::{admission_tests::Fixture,deterministic_runtime_tests::{draft_with,queued,owned},lease_controller::dispatcher::{self,Driver,Environment,Phase},recipe_decisions::{Source,Decision,Origin},store::Store,criteria::NATIVE_MESSAGE_CRITERION};
use std::sync::{Mutex,atomic::AtomicUsize};
fn settings()->crate::settings::Settings{let mut s=crate::settings::Settings::default();s.active_integrations=vec!["ai_ollama".into(),"integration_spotify".into()];s}
fn observe()->Observe{Arc::new(||Ok((crate::pet_config::defaults(),settings())))}
struct Env{delay_completion:bool,store_path:std::path::PathBuf,choice:Option<bool>,decisions:AtomicUsize,stop:bool,store:Arc<Store>,authority:std::path::PathBuf}
impl Environment for Env{
 fn capture(&self,_:&Owned)->model::Result<dispatcher::Capture>{panic!("native review must not capture a model")}
 fn configuration(&self)->model::Result<crate::pet_config::Configuration>{Ok(crate::pet_config::defaults())}
 fn peer_configuration(&self)->model::Result<(crate::pet_config::Configuration,crate::settings::Settings)>{Ok((crate::pet_config::defaults(),settings()))}
 fn target(&self)->model::Result<Arc<crate::spotify::goal::Target>>{panic!("native review must not require music permission or target")}
 fn notify(&self,s:&dispatcher::Status){
  if self.delay_completion&&s.phase==Phase::Feedback{use std::os::fd::AsRawFd;
   let lock=std::fs::OpenOptions::new().read(true).write(true).open(self.store_path.join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);
   std::thread::spawn(move||{std::thread::sleep(std::time::Duration::from_millis(180));drop(lock);});
  }
 }
 fn decide(&self,source:Source)->Option<Decision>{
  self.decisions.fetch_add(1,Ordering::AcqRel);assert_eq!(source.target().origin,Origin::GoalPeerPlan);assert!(source.current());let p=&source.review()["recipe"];assert_eq!(p["steps"].as_array().unwrap().len(),2);assert_eq!(source.review()["approvalScope"],"exactReviewedNativePeerPlan");assert_eq!(p["recipientExecutionAuthorized"],false);
  let g=self.store.read(&source.target().goal_id,&source.target().pet_id).unwrap();let a=Authority::existing(&self.authority).unwrap();for p in &g.plans{for s in &p.steps{assert!(a.message_at(&g.admissions[0].spec,g.admissions[0].proof.as_ref().unwrap(),&p.id,&s.id).unwrap().is_none());}}
  if self.stop{crate::pet_runtime::authority_store::mutate_with_authority(self.store.as_ref(),&self.authority,&g.id,&g.spec.owner.pet_id,&g.revision,nonce().unwrap(),model::Action::Cancel,crate::assistant_memory::now()).unwrap();assert!(!source.current());}
  if self.stop{return None;}self.choice.and_then(|c|{let fixture=crate::cli_chat::goal_decision_fixture(source);assert_eq!(fixture.panel_pending().len(),1);fixture.panel_answer(c,fixture.request["goalTarget"].clone()).unwrap();fixture.decision()})
 }
}
fn setup(provider:&str)->(Fixture,Authority,Record,Owned){let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft_with(&f,provider,vec![NATIVE_MESSAGE_CRITERION.into()],2);let q=queued(&f,&a,&g);assert!(!q.admissions[0].spec.execution_requested());let(g,o)=owned(&f,&a,&q,&crate::chat::Chat::persistent(f.path.join("main.json")));(f,a,g,o)}
fn run(f:&Fixture,o:Owned,choice:Option<bool>,stop:bool)->(Arc<Driver>,Arc<Env>,dispatcher::Status){run_with_delay(f,o,choice,stop,false)}
fn run_with_delay(f:&Fixture,o:Owned,choice:Option<bool>,stop:bool,delay_completion:bool)->(Arc<Driver>,Arc<Env>,dispatcher::Status){let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&f.path.join("authority")).unwrap().unwrap());let env=Arc::new(Env{delay_completion,store_path:f.path.join("goals"),choice,decisions:AtomicUsize::new(0),stop,store:store.clone(),authority:f.path.join("authority")});let d=Driver::new(Arc::new(o),store,env.clone()).unwrap();let rt=tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();let s=rt.block_on(d.run()).unwrap_or_else(|e|panic!("{e:?}: {:?}",d.status().unwrap()));(d,env,s)}
#[test]fn peer_sequence_review_runs_all_native_factory_identities_after_one_own_exact_decision(){for provider in ["codex","copilot","antigravity","ollama","lmstudio","openai","integration_spotify"]{let(f,a,g,o)=setup(provider);let(_d,env,status)=run(&f,o,Some(true),false);assert_eq!(status.phase,Phase::Completed);assert_eq!(env.decisions.load(Ordering::Acquire),1);let done=env.store.read(&g.id,&g.spec.owner.pet_id).unwrap();assert_eq!(done.state,model::State::Completed);assert_eq!(done.admissions.len(),1);assert_eq!(model::fingerprint(&done.admissions[0].spec).unwrap(),model::fingerprint(&g.admissions[0].spec).unwrap());assert!(done.admissions[0].spec.native_peer_plan.is_none());a.verify_completed_goal(&done).unwrap();}}
#[test]fn peer_sequence_decline_ended_review_and_stop_do_not_send_or_publish_false_success(){for(choice,stop,phase)in[(Some(false),false,Phase::Declined),(None,false,Phase::ApprovalEnded),(Some(true),true,Phase::Stopped)]{let(f,a,g,o)=setup("copilot");let(_d,env,status)=run(&f,o,choice,stop);assert_eq!(status.phase,phase);let current=env.store.read(&g.id,&g.spec.owner.pet_id).unwrap();assert!(current.completion.is_none());for p in &g.plans{for s in &p.steps{assert!(a.message_at(&g.admissions[0].spec,g.admissions[0].proof.as_ref().unwrap(),&p.id,&s.id).unwrap().is_none());}}}}
#[test]fn peer_sequence_decision_binds_the_exact_batch_owner_goal_and_is_consumed_once(){
 let(f,_a,g,o)=setup("ollama");let o=Arc::new(o);let config=crate::pet_config::defaults();let settings=settings();let now=crate::assistant_memory::now();let b=Batch::capture(&o,&g,&config,&settings,now).unwrap().unwrap();let st=Arc::new(Store::existing_verified(&f.path.join("goals"),&f.path.join("authority")).unwrap().unwrap());let(_foreign_f,_foreign_a,_foreign_g,foreign)=setup("ollama");assert!(Source::capture_peer(Arc::new(foreign),&g,b.clone(),st.clone(),observe()).is_err());let s=Source::capture_peer(o.clone(),&g,b.clone(),st.clone(),observe()).unwrap();let fixture=crate::cli_chat::goal_decision_fixture(s.clone());let mut wrong_target=fixture.request["goalTarget"].clone();wrong_target["goalId"]=serde_json::json!("wrong-native-goal");assert!(fixture.panel_answer(true,wrong_target).is_err());assert_eq!(fixture.count(),1);fixture.panel_answer(true,fixture.request["goalTarget"].clone()).unwrap();let decision=fixture.decision().unwrap();assert!(fixture.panel_answer(true,fixture.request["goalTarget"].clone()).is_err());assert!(Decision::from_transport(s,true).is_none());
 let other=Batch::capture(&o,&g,&config,&settings,now).unwrap().unwrap();assert!(other.approve(&decision,&o,&g,&observe(),now).is_err());let mut wrong=g.clone();wrong.spec.criteria[0]="Unreviewed criterion".into();assert!(b.approve(&decision,&o,&wrong,&observe(),now).is_err());let now=crate::assistant_memory::now();let approved=b.approve(&decision,&o,&g,&observe(),now).unwrap();assert_eq!(approved.len(),2);assert!(b.approve(&decision,&o,&g,&observe(),now).is_err());
 let r=o.send_message(&g,&approved[0],now,||Ok((config.clone(),settings.clone()))).unwrap();let ack=o.send_message(&g,&approved[0],now,||panic!("canonical ACK must be read before configuration")).unwrap();assert_eq!(r,ack);
}

#[test]fn peer_sequence_busy_completion_reuses_signed_report_and_never_resends_original_envelopes(){
 let(f,a,g,o)=setup("ollama");let(_d,env,status)=run_with_delay(&f,o,Some(true),false,true);assert_eq!(status.phase,Phase::Completed);assert_eq!(env.decisions.load(Ordering::Acquire),1);let done=env.store.read(&g.id,&g.spec.owner.pet_id).unwrap();a.verify_completed_goal(&done).unwrap();let row=&done.admissions[0];let report=a.native_completion(&row.spec,row.proof.as_ref().unwrap()).unwrap().unwrap();assert_eq!(report.receipts.len(),2);let body:serde_json::Value=serde_json::from_slice(&std::fs::read(f.path.join("authority").join(format!("{}.json",row.spec.decision_id))).unwrap()).unwrap();assert_eq!(body["body"]["messages"]["entries"].as_array().unwrap().len(),2);assert_eq!(body["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),2);
}
